draw:
var a = p.a, b = p.b;
var mEx = a + b, lEx = a - b, tEx = -2 * a;
var targ = [0, 1, -1];
var got = [mEx, lEx, tEx];
var names = ["M  (mass)", "L  (length)", "T  (time)"];
var pad = 74;
var x0 = pad, x1 = W - 16;
var mid = (x0 + x1) / 2;
var scale = (x1 - x0) / 2 / 2.6;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";
ctx.lineWidth = 1;

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("v = T_s^a mu^b   ->   M^(a+b) L^(a-b) T^(-2a)", 10, 16);
ctx.fillStyle = C.figure;
ctx.fillText("target for a speed:  M^0 L^1 T^-1", 10, 34);

var ok = true;
for (var i = 0; i < 3; i++) {
  var y = 62 + i * 34;
  ctx.strokeStyle = C.faint;
  ctx.beginPath(); ctx.moveTo(x0, y); ctx.lineTo(x1, y); ctx.stroke();
  ctx.strokeStyle = C.rule;
  ctx.beginPath(); ctx.moveTo(mid, y - 11); ctx.lineTo(mid, y + 11); ctx.stroke();

  ctx.fillStyle = C.ink;
  ctx.textAlign = "right";
  ctx.fillText(names[i], x0 - 8, y);

  var gx = mid + got[i] * scale;
  var tx = mid + targ[i] * scale;
  var hit = Math.abs(got[i] - targ[i]) < 0.01;
  if (!hit) ok = false;

  ctx.strokeStyle = C.accent;
  ctx.lineWidth = hit ? 5 : 3;
  ctx.beginPath(); ctx.moveTo(mid, y); ctx.lineTo(gx, y); ctx.stroke();
  ctx.lineWidth = 1;

  ctx.strokeStyle = C.figure;
  ctx.beginPath();
  ctx.moveTo(tx, y - 13); ctx.lineTo(tx - 5, y - 21); ctx.lineTo(tx + 5, y - 21);
  ctx.closePath(); ctx.stroke();

  ctx.fillStyle = C.figure;
  ctx.textAlign = "center";
  ctx.fillText(targ[i].toFixed(0), tx, y - 28);
  ctx.fillStyle = C.accent;
  ctx.fillText(got[i].toFixed(2), gx, y + 14);
}

if (ok) {
  var pulse = 0.55 + 0.45 * Math.sin(t * 3);
  ctx.globalAlpha = pulse;
  ctx.fillStyle = C.accent;
  ctx.textAlign = "center";
  ctx.fillText("all three match:  v = sqrt(T_s / mu)", W / 2, H - 12);
  ctx.globalAlpha = 1;
} else {
  ctx.fillStyle = C.figure;
  ctx.textAlign = "center";
  ctx.fillText("orange bar must reach the outlined marker on every row", W / 2, H - 12);
}

out.note = "a = " + a.toFixed(2) + ", b = " + b.toFixed(2) +
  "   M: " + mEx.toFixed(2) + " (need 0), L: " + lEx.toFixed(2) +
  " (need 1), T: " + tEx.toFixed(2) + " (need -1)" + (ok ? "  SOLVED" : "");
